#!/usr/bin/env node
/* global process, console */
// Regenerates src/clients/ethereum/artifacts from a Foundry build of
// github.com/gnolang/gno-eth-ibc (GnoLightClient, and the solidity-ibc-eureka
// v3.0.2 ICS26Router it vendors):
//
//   (cd $GNO_ETH_IBC && make build)
//   GNO_ETH_IBC=../gnolang/gno-eth-ibc pnpm gen:eth-artifacts
//
// The source commit is recorded in each generated file.
import {
  execFileSync,
} from "node:child_process";
import {
  readFileSync, writeFileSync,
} from "node:fs";
import {
  dirname, join, resolve,
} from "node:path";
import {
  fileURLToPath,
} from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, "..");
const src = resolve(root, process.env.GNO_ETH_IBC ?? "../gnolang/gno-eth-ibc");
const outDir = join(root, "src/clients/ethereum/artifacts");

const git = (...args) => execFileSync("git", ["-C", src, ...args], {
  encoding: "utf8",
}).trim();
const commit = git("rev-parse", "HEAD");
const dirty = git("status", "--porcelain", "contracts/src").length > 0 ? " (with uncommitted changes in contracts/src)" : "";

function artifact(name) {
  return JSON.parse(readFileSync(join(src, "contracts/out", `${name}.sol`, `${name}.json`), "utf8"));
}

function write(file, name, withBytecode) {
  const a = artifact(name);
  const lines = ["/* eslint-disable max-lines */", "// Generated by scripts/gen-eth-artifacts.mjs from a Foundry build of", `// github.com/gnolang/gno-eth-ibc at ${commit}${dirty}. Do not edit.`, "", `export const ${name[0].toLowerCase()}${name.slice(1)}Abi = ${JSON.stringify(a.abi, null, 2)} as const;`];
  if (withBytecode) {
    lines.push("", `export const ${name[0].toLowerCase()}${name.slice(1)}Bytecode = "${a.bytecode.object}" as const;`);
  }
  const path = join(outDir, file);
  writeFileSync(path, lines.join("\n") + "\n");
  return path;
}

const files = [write("GnoLightClient.ts", "GnoLightClient", true), write("ICS26Router.ts", "ICS26Router", false)];
execFileSync("pnpm", ["exec", "eslint", "--fix", ...files], {
  cwd: root,
  stdio: "inherit",
});
console.log(`wrote ${files.join(", ")} from ${commit}${dirty}`);
